const freeView=createFreeView({element:renderer.domElement,speedInput:$('#free-speed'),speedLabel:$('#free-speed-value'),altitudeLabel:$('#free-altitude'),movePad:$('#free-move-pad'),lookPad:$('#free-look-pad'),riseButtons:[...document.querySelectorAll('[data-free-rise]')]});
let freeSnapshot=null;
