  if(!onlyId||onlyId.startsWith('CHENGXU-')){const m=courtyardIntegration.model;modules.push({id:m.manifest.id,blockId:courtyardIntegration.site.blockId,position:m.root.position.toArray(),source:'./courtyard-model.js',snapshotSpace:'world',snapshot:m.exportScene(onlyId)});}
  if(!onlyId||onlyId.startsWith('HENGLIAN-')){const m=headquartersIntegration.model;modules.push({id:m.manifest.id,blockId:headquartersIntegration.site.blockId,position:m.root.position.toArray(),source:'./headquarters-model.js',snapshotSpace:'world',snapshot:m.exportScene(onlyId)});}
